import{_ as n,c as i,d as h,o as c}from"./index-B0m5hkHn.js";const a={};function e(s,t){return c(),i("div",null,[...t[0]||(t[0]=[h('<section class="tf-page-title"><div class="container"><div class="box-title text-center"><h4 class="title">Giao hàng</h4><div class="breadcrumb-list"><a class="breadcrumb-item" href="index.html">Trang chủ</a><div class="breadcrumb-item dot"><span></span></div><div class="breadcrumb-item current">Giao hàng</div></div></div></div></section><section class="s-term-user flat-spacing-13"><div class="container"><div class="content"><div class="term-item"><h4>Chính sách giao hàng</h4><br><br><p class="term-text body-text text-main"> Cảm ơn quý khách đã tin tưởng và mua sắm tại <strong>Laptop Lâm Phát</strong>. Chúng tôi luôn nỗ lực mang đến dịch vụ giao hàng nhanh chóng, an toàn và tiện lợi nhất cho quý khách trên toàn quốc. Dưới đây là chính sách giao hàng áp dụng tại cửa hàng của chúng tôi: </p><br><br></div><div class="term-item"><p class="term-title">1. Khu Vực Giao Hàng</p><div class="text-wrap"><p class="term-text body-text text-main"><strong>1.1. Nội thành TP. Hồ Chí Minh</strong><br> – Phạm vi: Quận 1, 3, 5, 10, Phú Nhuận, Bình Thạnh, Gò Vấp, Tân Bình, Tân Phú, Bình Thạnh, Quận 2, Quận 7.<br> – Thời gian: 1–2 ngày làm việc.<br> – Dịch vụ giao nhanh trong ngày (từ 2–4 tiếng) tuỳ khu vực.<br> – Phí giao: 20.000 ₫ – 30.000 ₫.<br> – <strong>Miễn phí giao hàng</strong> cho đơn hàng từ 1.000.000 ₫ trở lên. </p><p class="term-text body-text text-main"><strong>1.2. Ngoại thành TP. Hồ Chí Minh</strong><br> – Phạm vi: Hóc Môn, Củ Chi, Nhà Bè, Bình Chánh, Cần Giờ.<br> – Thời gian: 2–3 ngày làm việc.<br> – Phí giao: 25.000 ₫ – 40.000 ₫.<br> – Hỗ trợ COD (thu hộ tiền mặt). </p><p class="term-text body-text text-main"><strong>1.3. Liên tỉnh (Toàn quốc)</strong><br> – Phạm vi: Giao hàng đến tất cả các tỉnh, thành phố trên toàn quốc.<br> – Thời gian: 3–7 ngày làm việc (tuỳ khoảng cách và điều kiện địa phương).<br> – Phí giao: 30.000 ₫ – 60.000 ₫ (có thể thay đổi theo kích thước, trọng lượng và vùng sâu vùng xa).<br> – Hỗ trợ COD toàn quốc. </p></div></div><div class="term-item"><p class="term-title">2. Đơn Vị Vận Chuyển</p><div class="text-wrap"><p class="term-text body-text text-main"> Chúng tôi liên kết với các đơn vị vận chuyển uy tín: Giao Hàng Nhanh (GHN), Giao Hàng Tiết Kiệm (GHTK), Viettel Post, VNPost (EMS) và AhaMove (nội thành siêu tốc). </p></div></div><div class="term-item"><p class="term-title">3. Quy Trình Xử Lý &amp; Huỷ Đơn</p><div class="text-wrap"><p class="term-text body-text text-main"> – Đơn hàng được xử lý và bàn giao cho vận chuyển trong vòng 1–2 ngày làm việc kể từ khi xác nhận thanh toán.<br> – Đơn hàng đặt vào cuối tuần hoặc ngày lễ sẽ được xử lý vào ngày làm việc tiếp theo.<br> – Quý khách có thể yêu cầu huỷ trong vòng <strong>6 giờ</strong> kể từ khi đặt hàng bằng cách liên hệ Hotline/Zalo. Sau khi đơn đã có mã vận chuyển, chúng tôi không thể hỗ trợ huỷ. </p></div></div><div class="term-item"><p class="term-title">4. Phí Giao Hàng</p><p class="term-text body-text text-main"> Phí giao hàng được tính dựa trên trọng lượng, kích thước, khu vực và phương thức vận chuyển. Chi phí chính xác sẽ hiển thị tại bước thanh toán trước khi quý khách xác nhận. </p></div><div class="term-item"><p class="term-title">5. Chậm Trễ &amp; Trường Hợp Ngoại Lệ</p><div class="text-wrap"><p class="term-text body-text text-main"> Trong các trường hợp bất khả kháng như mưa bão, kẹt xe, cấm đường, ngày lễ/tết cao điểm, thời gian giao hàng có thể kéo dài hơn dự kiến. Mong quý khách thông cảm và liên hệ để được hỗ trợ. </p></div></div><div class="term-item"><div class="text-wrap"><p class="term-text body-text text-main"> Mọi thắc mắc về chính sách giao hàng, xin vui lòng liên hệ:<br> 📞 Hotline/Zalo: <strong>0973270102</strong><br> 📍 Địa chỉ: 366/4 Chu văn An Ho Chi Minh City, Vietnam<br> ✉️ Email: <a href="mailto:lamphatcommerce@gmail.com" class="link body-text fw-medium">lamphatcommerce@gmail.com</a></p></div></div></div></div></section>',2)])])}const o=n(a,[["render",e]]);export{o as default};
